#include <iostream>
#include <vector>
#include <algorithm>
#include <cstddef>

int main() {
    std::vector<int> original{6, 2, 6, 1};
    auto ordenados = original;
    std::sort(ordenados.begin(), ordenados.end());
    std::cout << "Original :";
    for (int valor : original) { std::cout << valor << ";"; }
    std::cout << "\nTriés :";
    for (int valor : ordenados) { std::cout << valor << ";"; }
    int distintos = 0;
    for (std::size_t i = 0; i < ordenados.size(); ++i) {
        if (i == 0 || ordenados[i] != ordenados[i - 1]) { ++distintos; }
    }
    std::cout << "\nDistincts :" << distintos;
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <cstddef>

int main() {
    std::vector<int> datos{9, 3, 7};
    std::sort(datos.begin(), datos.end());
    std::size_t posicion = datos.size();
    for (std::size_t i = 0; i < datos.size() && posicion == datos.size(); ++i) {
        if (datos[i] == 9) { posicion = i; }
    }
    if (posicion < datos.size()) { std::cout << posicion; }
    else { std::cout << "Absent"; }
    return 0;
}
